-- 0006: notifications, coupons, reviews, support, audit, platform
create table public.notification_templates (id uuid primary key default gen_random_uuid(), business_id uuid references public.businesses(id) on delete cascade, template_key text not null, channel public.notification_channel not null default 'email', locale text not null check (locale in ('en','bn')), subject text, body text not null, is_active boolean not null default true, created_at timestamptz not null default now(), unique(business_id, template_key, channel, locale));
create table public.notification_jobs (id uuid primary key default gen_random_uuid(), business_id uuid references public.businesses(id) on delete cascade, template_key text not null, channel public.notification_channel not null, recipient text not null, payload jsonb not null default '{}'::jsonb, status public.notification_status not null default 'queued', attempts int not null default 0, max_attempts int not null default 3, run_at timestamptz not null default now(), created_at timestamptz not null default now());
create index notification_jobs_status_idx on public.notification_jobs(status, run_at);
create table public.notification_logs (id uuid primary key default gen_random_uuid(), business_id uuid references public.businesses(id) on delete cascade, job_id uuid references public.notification_jobs(id) on delete set null, channel public.notification_channel not null, recipient text not null, status public.notification_status not null, provider_ref text, error text, created_at timestamptz not null default now());
create table public.coupons (id uuid primary key default gen_random_uuid(), business_id uuid references public.businesses(id) on delete cascade, code text not null, percent_off int check (percent_off between 0 and 100), amount_off_minor bigint, min_spend_minor bigint not null default 0, max_redemptions int, starts_at timestamptz, expires_at timestamptz, is_active boolean not null default true, created_at timestamptz not null default now(), unique(business_id, code));
create table public.coupon_redemptions (id uuid primary key default gen_random_uuid(), business_id uuid not null references public.businesses(id) on delete cascade, coupon_id uuid not null references public.coupons(id) on delete cascade, appointment_id uuid references public.appointments(id), discount_minor bigint not null default 0, created_at timestamptz not null default now());
create table public.reviews (id uuid primary key default gen_random_uuid(), business_id uuid not null references public.businesses(id) on delete cascade, appointment_id uuid references public.appointments(id) on delete set null, customer_id uuid references public.customers(id) on delete set null, rating int not null check (rating between 1 and 5), comment text, is_published boolean not null default true, created_at timestamptz not null default now());
create index reviews_biz_idx on public.reviews(business_id);
create table public.support_tickets (id uuid primary key default gen_random_uuid(), business_id uuid references public.businesses(id) on delete set null, opened_by uuid references public.profiles(id), subject text not null, status text not null default 'open', priority text not null default 'normal', created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.support_messages (id uuid primary key default gen_random_uuid(), ticket_id uuid not null references public.support_tickets(id) on delete cascade, author_user_id uuid references public.profiles(id), body text not null, created_at timestamptz not null default now());
create table public.audit_logs (id uuid primary key default gen_random_uuid(), business_id uuid references public.businesses(id) on delete set null, actor_user_id uuid references public.profiles(id), action text not null, entity_type text, entity_id uuid, payload jsonb not null default '{}'::jsonb, ip_address inet, created_at timestamptz not null default now());
create index audit_biz_idx on public.audit_logs(business_id, created_at desc);
create table public.platform_settings (key text primary key, value jsonb not null default '{}'::jsonb, updated_at timestamptz not null default now());
create table public.api_keys (id uuid primary key default gen_random_uuid(), business_id uuid not null references public.businesses(id) on delete cascade, name text not null, key_hash text not null unique, scopes text[] not null default '{}', last_used_at timestamptz, expires_at timestamptz, created_at timestamptz not null default now(), revoked_at timestamptz);
create table public.webhook_endpoints (id uuid primary key default gen_random_uuid(), business_id uuid not null references public.businesses(id) on delete cascade, url text not null, secret_hash text, events text[] not null default '{}', is_active boolean not null default true, created_at timestamptz not null default now());
create table public.webhook_deliveries (id uuid primary key default gen_random_uuid(), business_id uuid references public.businesses(id) on delete cascade, endpoint_id uuid references public.webhook_endpoints(id) on delete set null, provider text, provider_event_id text, event_type text not null, payload jsonb not null default '{}'::jsonb, status text not null default 'pending', attempts int not null default 0, created_at timestamptz not null default now(), unique(provider, provider_event_id));
create table public.custom_pages (id uuid primary key default gen_random_uuid(), business_id uuid references public.businesses(id) on delete cascade, slug text not null, title text not null, body text, is_published boolean not null default false, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(business_id, slug));
create trigger support_tickets_updated before update on public.support_tickets for each row execute function public.set_updated_at();
